(function(){const db=window.RECIPES_INGREDIENTS;const rnd=x=>Math.round(x*10)/10;for(const r of window.RECIPES_DATA){if(!r.ingredientsStructured)continue;let total=[0,0,0,0,0],mass=0;for(const it of r.ingredientsStructured){const item=db[it.ingredientId];if(!item)throw Error('Unknown ingredient '+it.ingredientId);mass+=it.amount;item.per100.forEach((v,i)=>total[i]+=v*it.amount/100)}let estimated=Number(r.estimatedCookedWeightG);if(estimated>0)mass=estimated;let servings=r.yieldServings;r.nutrition={servings,portionG:Math.round(mass/servings),perPortion:total.map(x=>rnd(x/servings)),per100:total.map(x=>rnd(x*100/mass)),basis:r.estimatedCookedWeightG?'КБЖУ на порцию: сумма по всем ингредиентам / 2. Крупы взвешены сухими, нут и фасоль — отваренными без жидкости; мясо и рыба — сырыми, креветки — варёными. Всё масло и соус включены. Масса готового блюда '+r.estimatedCookedWeightG+' г оценочная, не измеренная; показатели на 100 г и категория калорийности зависят от фактического выхода. Соль и специи сверх указанной граммовки не включены. Углеводы по исходному справочнику, без вычитания клетчатки.':'Расчёт по структурированным ингредиентам и усреднённым справочным данным. Масса после приготовления, потери воды и необязательные добавки не учтены.'};r.kcal=r.nutrition.per100[0];r.fiber=r.nutrition.per100[4];r.cal=r.kcal<100?'низкая':r.kcal<=200?'средняя':'высокая'}})();
window.RECIPES_NUTRIENTS={fields:['ккал','белки','жиры','углеводы','клетчатка'],note:'Оценочные расчёты, не лабораторные значения.'};
